13	import { computeImportPlan, type ExistingTransactionRow } from '$lib/utils/transactionDedup'; // #{#tid2a}
14	
15	export class TransactionService {
16		private static instance: TransactionService;
17	
18		private constructor() {}
19	
20		static get(): TransactionService {
21			if (!TransactionService.instance) {
22				TransactionService.instance = new TransactionService();
23			}
24			return TransactionService.instance;
25		}
26	
27		/**
28		 * List transactions for a family with optional filtering and sorting
29		 */
30		async list(
31			familyId: string,
32			options?: {
33				sort?: 'transaction_date' | 'vendor_name' | 'amount' | 'credit_card_type';
34				direction?: 'asc' | 'desc';
35				includeExcluded?: boolean;
36				creditCardType?: CreditCardType;
37			}
38		): Promise<TransactionRow[]> {
39			let query = supabase.from('transactions').select('*').eq('family_id', familyId);
40	
41			// Filter excluded transactions
42			if (!options?.includeExcluded) {
43				query = query.eq('excluded', false);
44			}
45	
46			// Filter by credit card type
47			if (options?.creditCardType) {
48				query = query.eq('credit_card_type', options.creditCardType);
49			}
50	
51			// Apply sorting
52			const sortColumn = options?.sort || 'transaction_date';
53			const ascending = options?.direction === 'asc';
54			query = query.order(sortColumn, { ascending });
55	
56			const { data, error } = await query;
57	
58			if (error) {
59				throw new Error(`Failed to load transactions: ${error.message}`);
60			}
61	
62			return data || [];
63		}
64	
65		/**
66		 * Get a single transaction by ID
67		 */
68		async get(id: string): Promise<TransactionRow> {
69			const { data, error } = await supabase.from('transactions').select('*').eq('id', id).single();
70	
71			if (error) {
72				throw new Error(`Failed to load transaction: ${error.message}`);
73			}
74	
75			return data;
76		}
77	
78		/**
79		 * Create a new transaction
80		 */
81		async create(transaction: TransactionInsert): Promise<TransactionRow> {
82			const { data, error } = await supabase
83				.from('transactions')
84				.insert(transaction)
85				.select()
86				.single();
87	
88			if (error) {
89				throw new Error(`Failed to create transaction: ${error.message}`);
90			}
91	
92			return data;
93		}
94	
95		/**
96		 * Update an existing transaction
97		 */
98		async update(id: string, updates: TransactionUpdate): Promise<TransactionRow> {
99			const { data, error } = await supabase
100				.from('transactions')
101				.update(updates)
102				.eq('id', id)
103				.select()
104				.single();
105	
106			if (error) {
107				throw new Error(`Failed to update transaction: ${error.message}`);
108			}
109	
110			return data;
111		}
112	
113		/**
114		 * Delete a transaction
115		 */
116		async delete(id: string): Promise<void> {
117			const { error } = await supabase.from('transactions').delete().eq('id', id);
118	
119			if (error) {
120				throw new Error(`Failed to delete transaction: ${error.message}`);
121			}
122		}
123	
124		/**
125		 * Delete multiple transactions by id (selection-based bulk delete).
126		 */
127		async deleteByIds(ids: string[]): Promise<void> {
128			if (ids.length === 0) return;
129			const { error } = await supabase.from('transactions').delete().in('id', ids);
130	
131			if (error) {
132				throw new Error(`Failed to delete transactions: ${error.message}`);
