142	
143		/**
144		 * Parse CSV/XLS/XLSX file and return parsed transactions - #{#xls2b}
145		 */
146		async parseCSV(
147			file: File,
148			creditCardType: CreditCardType
149		): Promise<{
150			transactions: ParsedTransaction[];
151			errors: string[];
152			detectedType?: CreditCardType;
153		}> {
154			return new Promise((resolve, reject) => {
155				const reader = new FileReader();
156	
157				reader.onload = (e) => {
158					try {
159						let csvContent: string;
160	
161						if (isExcelFile(file)) {
162							const buffer = e.target?.result as ArrayBuffer;
163							csvContent = convertExcelToCSV(buffer);
164						} else {
165							csvContent = e.target?.result as string;
166						}
167	
168						// Get the appropriate parser
169						const parser = CSVParserFactory.getParser(creditCardType);
170	
171						// Validate format
172						if (!parser.validateFormat(csvContent)) {
173							resolve({
174								transactions: [],
175								errors: [
176									`The file does not match the expected format for ${creditCardType}. Please verify you selected the correct credit card type.`
177								]
178							});
179							return;
180						}
181	
182						// Parse the CSV
183						const result = parser.parse(csvContent);
184						resolve({
185							transactions: result.transactions,
186							errors: result.errors
187						});
188					} catch (error: any) {
189						reject(new Error(`Failed to parse file: ${error.message || 'Unknown error'}`));
190					}
191				};
192	
193				reader.onerror = () => {
194					reject(new Error('Failed to read file'));
195				};
196	
197				if (isExcelFile(file)) {
198					reader.readAsArrayBuffer(file);
199				} else {
200					reader.readAsText(file);
201				}
202			});
203		}
204	
205		/**
206		 * Auto-detect file format and parse - #{#xls2c}
207		 */
208		async parseCSVAuto(file: File): Promise<{
209			transactions: ParsedTransaction[];
210			errors: string[];
211			detectedType: CreditCardType | null;
212		}> {
213			return new Promise((resolve, reject) => {
214				const reader = new FileReader();
215	
216				reader.onload = (e) => {
217					try {
218						let csvContent: string;
219	
220						if (isExcelFile(file)) {
221							const buffer = e.target?.result as ArrayBuffer;
222							csvContent = convertExcelToCSV(buffer);
223						} else {
224							csvContent = e.target?.result as string;
225						}
226	
227						// Try to detect the format
228						const detection = CSVParserFactory.detectParser(csvContent);
229	
230						if (!detection) {
231							resolve({
232								transactions: [],
233								errors: [
234									'Could not automatically detect the file format. Please manually select the credit card type.'
235								],
236								detectedType: null
237							});
238							return;
239						}
240	
241						// Parse the CSV
242						const result = detection.parser.parse(csvContent);
243						resolve({
244							transactions: result.transactions,
245							errors: result.errors,
246							detectedType: detection.creditCardType
247						});
248					} catch (error: any) {
249						reject(new Error(`Failed to parse file: ${error.message || 'Unknown error'}`));
250					}
251				};
252	
253				reader.onerror = () => {
254					reject(new Error('Failed to read file'));
255				};
256	
257				if (isExcelFile(file)) {
258					reader.readAsArrayBuffer(file);
259				} else {
260					reader.readAsText(file);
261				}
262			});
263		}
264	
265		/**
266		 * Import transactions from CSV/XLSX using count-based duplicate detection.
267		 *
268		 * Specifications: #{#tid1a} #{#tid2a} #{#tid2b} #{#tid5a}
269		 *
270		 * For each distinct `(transaction_date, vendor_name, amount)` key in the file,
271		 * inserts `max(0, fileCount - dbCount)` rows. Excluded (soft-deleted) rows count
272		 * toward `dbCount` so re-import does not resurrect them.
273		 */
274		async importFromCSV(
275			familyId: string,
276			file: File,
277			creditCardType: CreditCardType
278		): Promise<{
279			imported: number;
280			skipped: number;
281			errors: string[];
282		}> {
283			const parseResult = await this.parseCSV(file, creditCardType);
284	
285			if (parseResult.transactions.length === 0) {
286				return { imported: 0, skipped: 0, errors: parseResult.errors };
287			}
288	
289			const errors: string[] = [...parseResult.errors];
290	
291			// #{#tid2a}: single scoped query for existing rows in the file's date range.
292			// #{#tid2b}: scope to (family_id, credit_card_type).
293			// #{#tid5a}: no excluded filter — excluded rows count toward dbCount.
294			const dates = parseResult.transactions.map((t) => t.transaction_date);
295			const minDate = dates.reduce((a, b) => (a < b ? a : b));
296			const maxDate = dates.reduce((a, b) => (a > b ? a : b));
297	
298			const { data: existingRows, error: selectError } = await supabase
299				.from('transactions')
300				.select('transaction_date, vendor_name, amount')
301				.eq('family_id', familyId)
302				.eq('credit_card_type', creditCardType)
303				.gte('transaction_date', minDate)
304				.lte('transaction_date', maxDate);
305	
306			if (selectError) {
307				throw new Error(`Failed to load existing transactions: ${selectError.message}`);
308			}
309	
310			const plan = computeImportPlan(
311				parseResult.transactions,
312				(existingRows ?? []) as ExistingTransactionRow[]
313			);
314	
315			if (plan.toInsert.length === 0) {
316				return { imported: 0, skipped: plan.skipped, errors };
317			}
318	
319			const rowsToInsert = plan.toInsert.map((t) => ({
320				family_id: familyId,
321				transaction_date: t.transaction_date,
322				vendor_name: t.vendor_name,
323				amount: t.amount,
324				credit_card_type: creditCardType
325			}));
326	
327			const { error: insertError } = await supabase.from('transactions').insert(rowsToInsert);
328	
329			if (insertError) {
330				errors.push(`Failed to insert transactions: ${insertError.message}`);
331				return { imported: 0, skipped: plan.skipped, errors };
332			}
333	
334			return { imported: plan.toInsert.length, skipped: plan.skipped, errors };
335		}
336	
337		/**
338		 * Get transaction statistics for a family
339		 */
340		async getStats(familyId: string): Promise<{
341			totalTransactions: number;
342			totalAmount: number;
343			byCardType: Record<string, { count: number; total: number }>;
344		}> {
345			const transactions = await this.list(familyId, { includeExcluded: false });
346	
347			const stats = {
348				totalTransactions: transactions.length,
349				totalAmount: 0,
350				byCardType: {} as Record<string, { count: number; total: number }>
351			};
352	
353			for (const transaction of transactions) {
354				stats.totalAmount += transaction.amount;
355	
356				if (!stats.byCardType[transaction.credit_card_type]) {
357					stats.byCardType[transaction.credit_card_type] = { count: 0, total: 0 };
358				}
359	
360				stats.byCardType[transaction.credit_card_type].count++;
361				stats.byCardType[transaction.credit_card_type].total += transaction.amount;
362			}
363	
364			return stats;
365		}
366	
367		/**
368		 * Delete all transactions for a family (with optional filters) - #{#tbd1b}
369		 */
370		async deleteAll(
371			familyId: string,
372			options?: {
373				creditCardType?: CreditCardType;
374				beforeDate?: string;
375				afterDate?: string;
376			}
377		): Promise<number> {
378			// Count matching transactions before deleting
379			let countQuery = supabase
380				.from('transactions')
381				.select('id', { count: 'exact', head: true })
382				.eq('family_id', familyId);
383	
384			if (options?.creditCardType) {
385				countQuery = countQuery.eq('credit_card_type', options.creditCardType);
386			}
387			if (options?.afterDate) {
388				countQuery = countQuery.gte('transaction_date', options.afterDate);
389			}
390			if (options?.beforeDate) {
391				countQuery = countQuery.lt('transaction_date', options.beforeDate);
392			}
393	
394			const { count } = await countQuery;
395	
396			// Delete with the same filters
397			let deleteQuery = supabase.from('transactions').delete().eq('family_id', familyId);
398	
399			if (options?.creditCardType) {
400				deleteQuery = deleteQuery.eq('credit_card_type', options.creditCardType);
401			}
402			if (options?.afterDate) {
403				deleteQuery = deleteQuery.gte('transaction_date', options.afterDate);
404			}
405			if (options?.beforeDate) {
406				deleteQuery = deleteQuery.lt('transaction_date', options.beforeDate);
407			}
408	
409			const { error } = await deleteQuery;
410	
411			if (error) {
412				throw new Error(`Failed to delete transactions: ${error.message}`);
413			}
414	
415			return count || 0;
416		}
417	}
