async getExpenses(userId: string, filters?: ExpenseFilters): Promise<Expense[]> {
	// Requirement: User ID validation
	if (!userId) {
		throw new Error('User ID is required');
	}

	// Build query: Join receipts with expense_categories and categories
	// This creates the "computed view" of expenses from receipts
	// #{#umf1b} - Added matched_transaction_id to support unmatched filter
	// Don't filter by user_id - let RLS policies handle access based on family membership
	let query = this.supabase.from('receipts').select(
		`
			id,
			merchant_name,
			total_amount,
			transaction_date,
			receipt_image_path,
			matched_transaction_id,
			currency,
			exchange_rate_to_cad,
			expense_categories (
				category_id,
				categorization_source,
				categories (
					name,
					color
				)
			)
		`
	);

	// Apply filters if provided
	if (filters?.startDate) {
		query = query.gte('transaction_date', filters.startDate);
	}

	if (filters?.endDate) {
		query = query.lte('transaction_date', filters.endDate);
	}

	if (filters?.merchantName) {
		query = query.ilike('merchant_name', `%${filters.merchantName}%`);
	}

	// Default sort: transaction_date descending (newest first)
	query = query.order('transaction_date', { ascending: false });

	// Execute query
	const { data, error } = await query;

	if (error) {
		throw new Error(error.message);
	}

	// Transform database results into Expense objects
	// Handle 1:1 mapping: each receipt → one expense
	// #{#umf1b} - Include matched_transaction_id in transformation
	const expenses: Expense[] = (data || []).map((receipt: any) => {
		const expenseCategory = receipt.expense_categories;
		const category = expenseCategory?.categories;

		return {
			receipt_id: receipt.id,
			merchant_name: receipt.merchant_name,
			total_amount: receipt.total_amount,
			transaction_date: receipt.transaction_date,
			receipt_image_path: receipt.receipt_image_path,
			category_id: expenseCategory?.category_id || null,
			categorization_source: expenseCategory?.categorization_source || null,
			category_name: category?.name || null,
			category_color: category?.color || null,
			matched_transaction_id: receipt.matched_transaction_id || null,
			currency: receipt.currency || null,
			exchange_rate_to_cad: receipt.exchange_rate_to_cad ?? null
		};
	});

	// Apply category filter after transformation (if needed)
	// Note: For better performance, this could be moved to the SQL query
	// but current schema makes it complex due to LEFT JOIN structure
	let filteredExpenses = expenses;
	if (filters?.categoryId) {
		filteredExpenses = expenses.filter((expense) => expense.category_id === filters.categoryId);
	}

	return filteredExpenses;
}

